// Loads testdata/providers.json, the data of the PHPUnit data providers in
// composer/semver's tests (generated by tools/oracle/semver/providers.php).

package semver

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"sync"
	"testing"
)

// phpArray is a decoded PHP array: keys (int64 or string) and values, in
// order.
type phpArray struct {
	keys   []any
	values []any
}

// providerCase is one data set of a data provider: its key and arguments.
type providerCase struct {
	name string
	args []any
}

var loadProviders = sync.OnceValues(func() (map[string]json.RawMessage, error) {
	data, err := os.ReadFile("testdata/providers.json")
	if err != nil {
		return nil, err
	}
	var providers map[string]json.RawMessage

	return providers, json.Unmarshal(data, &providers)
})

// provider returns the data sets of the named provider, e.g.
// "VersionParserTest::successfulNormalizedVersions".
func provider(t *testing.T, name string) []providerCase {
	t.Helper()
	providers, err := loadProviders()
	if err != nil {
		t.Fatal(err)
	}
	raw, ok := providers[name]
	if !ok {
		t.Fatalf("no provider %s", name)
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var v any
	if err := dec.Decode(&v); err != nil {
		t.Fatal(err)
	}
	sets := decodePHP(t, v).(*phpArray)
	cases := make([]providerCase, len(sets.keys))
	for i, key := range sets.keys {
		cases[i] = providerCase{name: fmt.Sprint(key), args: sets.values[i].(*phpArray).values}
	}
	if len(cases) == 0 {
		t.Fatalf("provider %s is empty", name)
	}

	return cases
}

// decodePHP turns the JSON encoding of providers.php back into values:
// string, bool, nil, int64, *phpArray, constraints and Bound.
func decodePHP(t *testing.T, v any) any {
	t.Helper()
	switch v := v.(type) {
	case json.Number:
		n, err := v.Int64()
		if err != nil {
			t.Fatal(err)
		}

		return n
	case map[string]any:
		switch {
		case v["a"] != nil:
			a := &phpArray{}
			for _, pair := range v["a"].([]any) {
				kv := pair.([]any)
				a.keys = append(a.keys, decodePHP(t, kv[0]))
				a.values = append(a.values, decodePHP(t, kv[1]))
			}

			return a
		case v["c"] != nil:
			c := v["c"].([]any)
			constraint, err := NewConstraint(c[0].(string), c[1].(string))
			if err != nil {
				t.Fatal(err)
			}

			return constraint
		case v["m"] != nil:
			m := v["m"].([]any)
			var constraints []ConstraintInterface
			for _, c := range m[1].([]any) {
				constraints = append(constraints, decodePHP(t, c).(ConstraintInterface))
			}
			multi, err := NewMultiConstraint(constraints, m[0].(bool))
			if err != nil {
				t.Fatal(err)
			}

			return multi
		case v["all"] != nil:
			return NewMatchAllConstraint()
		case v["none"] != nil:
			return NewMatchNoneConstraint()
		case v["bound"] != nil:
			b := v["bound"].([]any)

			return NewBound(b[0].(string), b[1].(bool))
		}
		t.Fatalf("cannot decode %v", v)
	}

	return v
}

// strings returns the values of a PHP list of strings.
func (a *phpArray) strings() []string {
	s := make([]string, len(a.values))
	for i, v := range a.values {
		s[i] = v.(string)
	}

	return s
}

// get returns the value at key k.
func (a *phpArray) get(k any) any {
	for i, key := range a.keys {
		if key == k {
			return a.values[i]
		}
	}

	return nil
}

// operatorConstants is the $map of the matchCompiled() test helpers.
func operatorConstant(t *testing.T, operator string) Op {
	t.Helper()
	op, ok := OperatorConstant(operator)
	if !ok {
		t.Fatalf("invalid operator %q", operator)
	}

	return op
}

// matchCompiled ports the matchCompiled() helper of ConstraintTest and
// MultiConstraintTest: it evaluates the compiled constraint with $v and
// $b set as CompilingMatcher sets them.
func matchCompiled(t *testing.T, constraint ConstraintInterface, operator, version string) bool {
	t.Helper()

	return constraint.compile(operatorConstant(t, operator)).eval(version, isBranch(version))
}

func mustConstraint(t *testing.T, operator, version string) *Constraint {
	t.Helper()
	c, err := NewConstraint(operator, version)
	if err != nil {
		t.Fatal(err)
	}

	return c
}

func mustMulti(t *testing.T, conjunctive bool, constraints ...ConstraintInterface) *MultiConstraint {
	t.Helper()
	c, err := NewMultiConstraint(constraints, conjunctive)
	if err != nil {
		t.Fatal(err)
	}

	return c
}

func mustParse(t *testing.T, constraints string) ConstraintInterface {
	t.Helper()
	c, err := VersionParser{}.ParseConstraints(constraints)
	if err != nil {
		t.Fatalf("ParseConstraints(%q): %v", constraints, err)
	}

	return c
}
